    @ApiOperation("批量操作-获取请假班级")
    public RVO<List<ClazzSimpleInfoVO>> getAllowLeaveClazzes(@RequestBody LeaveClazzesRequest request) {
        return RVO.data(studentListService.listUserUnEndedClazz(request));
    }

    @PostMapping("/leave/check")
    @ApiOperation("批量操作-请假校验")
    public RVO<Boolean> leaveCheck(@RequestBody StudentBatchLeaveRequest request) {
        return RVO.data(personLeaveBiz.leaveCheck(request));
    }

    /**
