import java.util.Objects;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/teacher")
public class TeacherInfoController {

    @Resource
    private TeacherBasicAclService teacherBasicAclService;

    @PostMapping("/current/account/info")
    public RVO<List<TeacherAccountInfoVO>> getCurrentTeacherAccountInfo(@RequestBody List<Integer> type) {
        Integer accountId = LoginInfoUtils.getLoginUser().getAccountId();
        List<TeacherInfoVO> teacherInfoVOList = teacherBasicAclService.queryByAccountIds(Collections.singletonList(accountId));
        if (CollectionUtils.isEmpty(teacherInfoVOList)) {
            return RVO.data(Collections.emptyList());
        }
        List<TeacherAccountInfoVO> result = teacherInfoVOList.stream()
                .filter(vo -> Objects.nonNull(vo.getBaseInfo()))
                .filter(vo -> CollectionUtils.isEmpty(type) || type.contains(vo.getBaseInfo().getType()))
                .map(vo -> {
                    TeacherAccountInfoVO item = new TeacherAccountInfoVO();
                    item.setName(vo.getBaseInfo().getName());
                    item.setNickName(vo.getBaseInfo().getNickName());
                    item.setTeacherNumber(vo.getNumber());
                    item.setType(vo.getBaseInfo().getType());
                    item.setTypeDesc(vo.getBaseInfo().getTypeDesc());
                    return item;
                })
                .collect(Collectors.toList());
        return RVO.data(result);
    }
}
