    /**
     * 批量操作-标记标签
     * 1. 判断入参type是否 = 1 ，是的话走新逻辑，学员老师维度。
     * 2. 不是走老逻辑，学员班级维度。
     */
    public void saveTagDetail(SaveTagRequest request, LoginInfo loginUser) {
        List<Integer> tagIds = request.getStudentTags();
        if (tagIds == null) {
            tagIds = Collections.emptyList();
        }

        if (Objects.equals(request.getType(), UserMarkTypeEnum.USER_ACCOUNT.getType())) {
            saveTagDetailUserAccount(request.getUserIds(), loginUser.getAccountId(), tagIds);
            return;
        }

        if (CollectionUtils.isEmpty(request.getClazzStudents())){
            throw BusinessException.of(BusinessErrorCode.PARAM_ERROR);
        }

        TagGroup tagGroup = temporaryTagService.buildTemporaryTag(tagIds);

        // 入参tag为空则清空标签，否则只有业务tag不为空时才更新标签
        if (CollectionUtils.isNotEmpty(tagGroup.getBusinessTags()) || CollectionUtils.isEmpty(tagIds)){
            userClazzMarkService.batchSaveTags(request.getClazzStudents(), loginUser.getAccountId(), tagGroup.getBusinessTags());

            // 双写原表
            this.saveTagDetailOld(loginUser.getTeacherNumber(), request.getClazzStudents(), tagGroup.getBusinessTags());
            // 双写es
            this.markInfoSync2Es(request.getClazzStudents(), null, null, tagGroup.getBusinessTags(), request.getScene());
        }

        if (CollectionUtils.isNotEmpty(tagGroup.getTemporaryTags())){
            List<Long> userIds =
                    request.getClazzStudents().stream().map(ClazzStudentVO::getUserId).distinct().collect(toList());
            temporaryTagService.saveTags(loginUser.getAccountId(), userIds, tagGroup.getTemporaryTags());
        }
    }

    /**
     * 1v1列表批量标记标签：
     * 1.区分临时标签和业务标签
     * 业务标签：入库后可在花名册筛选等操作。
     * 临时标签：借用业务标签壳子，不会落入业务库，直接通过好友关系推送到企微官方，老师去企微做批量发送等操作。
     */
    private void saveTagDetailUserAccount(List<Long> userIds, Integer accountId, List<Integer> tagIds) {
        if (CollectionUtils.isEmpty(userIds)){
            throw BusinessException.of(BusinessErrorCode.PARAM_ERROR);
        }

        TagGroup tagGroup = temporaryTagService.buildTemporaryTag(tagIds);

        // 入参tag为空则清空标签，否则只有业务tag不为空时才更新标签
        if (CollectionUtils.isNotEmpty(tagGroup.getBusinessTags()) || CollectionUtils.isEmpty(tagIds)){
            teacherUserMarkService.batchSaveTags(userIds, accountId, tagGroup.getBusinessTags());
        }

        if (CollectionUtils.isNotEmpty(tagGroup.getTemporaryTags())){
            temporaryTagService.saveTags(accountId, userIds, tagGroup.getTemporaryTags());
        }

    }

