    private List<SubclazzStudentDTO> listSubclazzStudentByClazzStudents(List<ClazzStudentVO> clazzStudentVOS){
        return clazzStudentVOS.stream().collect(groupingBy(ClazzStudentVO::getClazzNumber))
                .entrySet().stream().map(entry ->
                        clazzDistributionService.listSubclazzStudentByUserIdsAndClazzNumber(entry.getKey(),
                                Lists.transform(entry.getValue(), ClazzStudentVO::getUserId))
                ).flatMap(List::stream).collect(toList());
    }


