def invoke_http(
    project: Optional[str] = None,
    app_id: Optional[str] = None,
    path: str = "",
    body=None,
    method: str = "POST",
    traffic_env: str = "test",
    route: Optional[str] = None,
    refresh: bool = False,
    b_client: Optional[str] = None,
    extra_headers: Optional[dict] = None,
) -> dict:
    """按工程名(app_id) + 接口路径，自动从青舟网关路由解析出 fuwu 可调 URL 并调用。

    路由解析复用 `_route_resolve`(与 qingzhou-route 同一份实现)：默认命中本地硬编码
    路由表(不查青舟)，refresh=True 才实时查。走 fuwu 网关 + Cookie。
    route 传 pathInfo 可跳过匹配(接口路径不在任何 pathInfo 前缀下时用)。
    b_client 传 B 端页面接口所需的请求头 `b_client`（取值随页面所属端：EES 页面=EES、
    GPS 页面=GPS）；不传则不加该头，页面接口会因 staff 调用失败报 `{"code":42,"msg":"调用staff失败"}`。
    """
    import _route_resolve as _rr

    env = "prod" if _online(traffic_env) else "test"
    if route:
        pi = route.split("/**")[0].rstrip("/")
        ipath = path or ""
        rest = ipath[len(pi):] if pi and ipath.startswith(pi) else (
            "/" + ipath.lstrip("/") if ipath else "")
        resolved = {"ok": True, "url": _rr.fuwu_base({"pathInfo": route}, env) + rest,
                    "pathInfo": pi, "env": env, "appId": app_id or project}
    else:
        resolved = _rr.resolve_fuwu_call(service=project, app_id=app_id,
                                         interface_path=path, env=env, refresh=refresh)
    if not resolved.get("ok"):
        return {k: v for k, v in resolved.items()}

    url = resolved["url"]
    headers = {
        "accept": "*/*",
        "content-type": "application/json",
        "traffic-env": traffic_env,
        "user-agent": UA,
    }
    if b_client:
        headers["b_client"] = b_client
    if extra_headers:
        headers.update({k: v for k, v in extra_headers.items() if v is not None})
    curl = _curl_of(url, headers, None if method.upper() == "GET" else body)
    if method.upper() == "GET":
        resp = requests.get(url, headers=headers, proxies=PROXIES, verify=False, timeout=TIMEOUT)
    else:
        payload = json.dumps(body, ensure_ascii=False).encode("utf-8") if body is not None else None
        resp = requests.post(url, headers=headers, data=payload,
                             proxies=PROXIES, verify=False, timeout=TIMEOUT)

    out = {
        "ok": True,
        "url": url,
        "trafficEnv": traffic_env,
        "httpStatus": resp.status_code,
        "resolvedRoute": {k: resolved.get(k) for k in
                          ("appId", "pathInfo", "rewriteInfo", "statusInfo", "routeId")},
        "request": body,
        "curl": curl,
    }
    out.update(_trace_of(resp))
    try:
        out["response"] = resp.json()
    except ValueError:
        out["responseText"] = resp.text[:4000]
    return out

