package com.gaotu.yunying.student.center.app.service;

import static java.util.stream.Collectors.groupingBy;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import javax.annotation.Resource;

import org.apache.commons.collections4.CollectionUtils;
import org.springframework.stereotype.Service;

import com.baijia.uqun.core.entity.base.ReturnEntity;
import com.ctrip.framework.apollo.spring.annotation.ApolloJsonValue;
import com.gaotu.link.client.relation.dto.TeacherWechatInfo;
import com.gaotu.link.client.relation.dto.UserWechatRelationInfo;
import com.gaotu.link.client.relation.dto.WechatRelationContact;
import com.gaotu.yunying.student.center.acl.FriendRelationService;
import com.gaotu.yunying.student.center.acl.adapter.RobotFriendFeignAdapter;
import com.gaotu.yunying.student.center.acl.model.request.BatchSendTarget;
import com.gaotu.yunying.student.center.acl.model.request.FriendTagRequest;
import com.gaotu.yunying.student.center.domain.model.TagGroup;
import com.gaotu.yunying.student.center.infrastructure.exception.BusinessErrorCode;
import com.gaotu.yunying.student.center.infrastructure.exception.BusinessException;
import com.gaotu.yunying.student.center.infrastructure.exception.RpcErrorCode;
import com.gaotu.yunying.student.center.infrastructure.exception.RpcException;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;

import lombok.extern.slf4j.Slf4j;

/**
 * @author wangwei
 */
@Service
@Slf4j
public class TemporaryStudentTagServiceImpl {

    @Resource
    private FriendRelationService friendRelationService;

    @Resource
    private RobotFriendFeignAdapter robotFriendFeignClient;

    @ApolloJsonValue("${temporary.studentTag.ids:[101,102,103,104,105,106,107,108,109,110,111,112,113,114,115,116,117,118,119,120]}")
    private Set<Integer> temporaryTagIds;

    public Boolean isTemporaryTag(Integer tagId){
        return temporaryTagIds.contains(tagId);
    }

    public void saveTags(Integer accountId, List<Long> userIds, List<Integer> tagIds) {

        // 取老师的企微logic
        List<TeacherWechatInfo> teacherWechatInfos = friendRelationService.getTeacherWechatInfos(Long.valueOf(accountId));
        if (CollectionUtils.isEmpty(teacherWechatInfos)){
            log.info("getTeacherWechatInfos is empty, accountId:{}", accountId);
            throw BusinessException.withMsg(BusinessErrorCode.PARAM_ERROR, "未获取到老师的企微ID");
        }
        Set<String> teacherWechatIds =
                teacherWechatInfos.stream().map(TeacherWechatInfo::getWechatId).collect(Collectors.toSet());
        Map<String, Set<String>> teacherUsersWechatIdMap = Maps.newHashMapWithExpectedSize(teacherWechatIds.size());

        // 取老师学员的好友关系
        List<UserWechatRelationInfo> relations = friendRelationService.getRelation(Long.valueOf(accountId), userIds);
        List<WechatRelationContact> relationContacts = relations.stream().map(UserWechatRelationInfo::getWechatRelationContacts)
                .flatMap(List::stream).filter(WechatRelationContact::isFriend).collect(Collectors.toList());
        if (CollectionUtils.isEmpty(relationContacts)){
            log.info("getFriendRelations is empty, accountId:{}, userIds:{}", accountId, userIds);
            throw BusinessException.withMsg(BusinessErrorCode.PARAM_ERROR, "无与老师有好友关系的学员");
        }

        relationContacts.forEach(relationContact -> {
                    String wechatId = relationContact.getWechatId();
                    relationContact.getFriendRelations().forEach(friendRelation -> {
                        if (teacherWechatIds.contains(friendRelation.getTeacherWechatId())){
                            Set<String> userWechatIds =
                                    teacherUsersWechatIdMap.getOrDefault(friendRelation.getTeacherWechatId(),
                                            Sets.newHashSet());
                            userWechatIds.add(wechatId);
                            teacherUsersWechatIdMap.put(friendRelation.getTeacherWechatId(), userWechatIds);
                        }
                    });
                });

        List<BatchSendTarget> targetLists = teacherUsersWechatIdMap.entrySet().stream().map(entry -> {
            BatchSendTarget target = new BatchSendTarget();
            target.setSender(entry.getKey());
            target.setReceiverList(Lists.newArrayList(entry.getValue()));
            return target;
        }).collect(Collectors.toList());

        FriendTagRequest request = new FriendTagRequest();
        request.setTagList(tagIds.stream().map(String::valueOf).collect(Collectors.toList()));
        request.setTargetList(targetLists);
        request.setSourceDesc("ees");
        log.info("addExternalContactTag request:{}", request);
        ReturnEntity<Boolean> response;
        try {
            response = robotFriendFeignClient.addExternalContactTag(request);
        }catch (Exception e){
            log.warn("addExternalContactTag, e :", e);
            throw new RpcException(RpcErrorCode.SS_ROBOT_FACADE_ERROR);
        }
        if (Boolean.FALSE.equals(response.getData())){
            throw BusinessException.withMsg(BusinessErrorCode.PARAM_ERROR, response.getMsg());
        }
    }

    public TagGroup buildTemporaryTag(List<Integer> tagIds) {
        Map<Boolean, List<Integer>> tagIdsGroup = tagIds.stream().collect(groupingBy(this::isTemporaryTag));

        TagGroup tagGroup = new TagGroup();
        tagGroup.setTemporaryTags(tagIdsGroup.getOrDefault(Boolean.TRUE, Collections.emptyList()));
        tagGroup.setBusinessTags(tagIdsGroup.getOrDefault(Boolean.FALSE, Collections.emptyList()));
        return tagGroup;
    }
