package com.gaotu.yunying.student.center.domain.service.impl;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

import javax.annotation.Resource;

import org.apache.commons.collections4.CollectionUtils;
import org.apache.logging.log4j.util.Strings;
import org.springframework.stereotype.Service;

import com.alibaba.fastjson.JSONObject;
import com.baijia.misc.id.sdk.facade.IdClient;
import com.gaotu.yunying.student.center.domain.model.BatchOperateTaskDO;
import com.gaotu.yunying.student.center.domain.model.EditWkRemarkTaskParam;
import com.gaotu.yunying.student.center.domain.model.export.ExportJobTaskDO;
import com.gaotu.yunying.student.center.domain.service.BatchOperateService;
import com.gaotu.yunying.student.center.domain.service.WechatRelationService;
import com.gaotu.yunying.student.center.enums.ExportSourceTypeEnums;
import com.gaotu.yunying.student.center.infrastructure.dao.entity.DwsFuwuUserTeacherWechatInfo;
import com.gaotu.yunying.student.center.infrastructure.dao.service.DwsFuwuUserTeacherWechatInfoDao;
import com.gaotu.yunying.student.center.infrastructure.enums.BatchOperateJobTypeEnum;
import com.gaotu.yunying.student.center.infrastructure.enums.WechatRelationEnum;
import com.gaotu.yunying.student.center.infrastructure.enums.WechatTypeEnum;
import com.gaotu.yunying.student.center.infrastructure.util.LoginInfoUtils;

import lombok.extern.slf4j.Slf4j;

/**
 * @author lichenhao02
 * @date 2024-03-04 6:29 下午
 */
@Service
@Slf4j
public class WechatRelationServiceImpl implements WechatRelationService {

    @Resource
    private DwsFuwuUserTeacherWechatInfoDao dwsFuwuUserTeacherWechatInfoDao;
    @Resource
    private BatchOperateService batchOperateService;
    @Resource
    private IdClient idClient;

    @Override
    public boolean checkWkFriendRelation(List<Long> userIds) {
        if (userIds.isEmpty()) {
            return false;
        }
        Integer accountId = LoginInfoUtils.getLoginUser().getAccountId();
        // 获取企业微信好友
        List<DwsFuwuUserTeacherWechatInfo> wechatInfos =
                dwsFuwuUserTeacherWechatInfoDao.listByAccountAndUserIds(accountId.longValue(), userIds,
                        Collections.singletonList(WechatRelationEnum.FRIEND.getCode()),
                        Collections.singletonList(WechatTypeEnum.BUSINESS_WECHAT.getCode()));
        List<Long> wkFriends =
                wechatInfos.stream().map(DwsFuwuUserTeacherWechatInfo::getUserId).distinct().collect(Collectors.toList());
        return wkFriends.containsAll(userIds);
    }

    @Override
    public boolean createEditWkRemarkTask(List<Long> userIds, String wkRemarkTemplate) {
        if (CollectionUtils.isEmpty(userIds) || Strings.isBlank(wkRemarkTemplate)) {
            return false;
        }
        Integer accountId = LoginInfoUtils.getLoginUser().getAccountId();
        BatchOperateTaskDO batchOperateTaskDO = this.buildEditWkRemarkTask(accountId);
        List<DwsFuwuUserTeacherWechatInfo> wechatInfos =
                dwsFuwuUserTeacherWechatInfoDao.listByAccountAndUserIds(accountId.longValue(), userIds,
                        Collections.singletonList(WechatRelationEnum.FRIEND.getCode()),
                        Collections.singletonList(WechatTypeEnum.BUSINESS_WECHAT.getCode()));
        List<ExportJobTaskDO> exportJobTaskList =
                this.buildJobTaskDOList(batchOperateTaskDO.getNumber(), wechatInfos, wkRemarkTemplate);
        return batchOperateService.createBatchOperateTaskWithJobTask(batchOperateTaskDO, exportJobTaskList);
    }

    private BatchOperateTaskDO buildEditWkRemarkTask(Integer accountId) {
        BatchOperateTaskDO task = new BatchOperateTaskDO();
        task.setCreateAccountId(accountId);
        task.setTaskType(BatchOperateJobTypeEnum.WK_REMARK.getCode());
        Long number = idClient.getId();
        task.setNumber(number);
        task.setSourceType(ExportSourceTypeEnums.SELF.getType());
        task.setSourceId(number);
        return task;
    }

    private List<ExportJobTaskDO> buildJobTaskDOList(Long taskNumber, List<DwsFuwuUserTeacherWechatInfo> wechatInfos, String wkRemarkTemplate) {
        List<ExportJobTaskDO> exportJobTaskList = new ArrayList<>();

        wechatInfos.forEach(wechatInfo -> {
            EditWkRemarkTaskParam editWkRemarkTaskParam = new EditWkRemarkTaskParam();
            editWkRemarkTaskParam.setUserId(wechatInfo.getUserId());
            editWkRemarkTaskParam.setAccountId(wechatInfo.getAccountId());
            editWkRemarkTaskParam.setUserWechatId(wechatInfo.getUserWechatId());
            editWkRemarkTaskParam.setAccountWechatId(wechatInfo.getAccountWechatId());
            editWkRemarkTaskParam.setWechatRemark(wechatInfo.getWechatRemark());
            editWkRemarkTaskParam.setWkRemarkTemplate(wkRemarkTemplate);
            ExportJobTaskDO exportJobTaskDO = new ExportJobTaskDO();
            exportJobTaskDO.setNumber(idClient.getId());
            exportJobTaskDO.setJobNumber(taskNumber);
            exportJobTaskDO.setBizNumber(wechatInfo.getUserId().toString());
            String params = JSONObject.toJSONString(editWkRemarkTaskParam);
            exportJobTaskDO.setParams(params);
            exportJobTaskDO.setBizDealType(BatchOperateJobTypeEnum.WK_REMARK.getCode());
            exportJobTaskList.add(exportJobTaskDO);
        });
        return exportJobTaskList;
    }
}

