 */
@Data
@TableName(value = "ees_data.batch_operate_task")
public class BatchOperateTask {
    /**
     * 主键id
     */
    @TableId(value = "id", type = IdType.AUTO)
    private Long id;

    /**
     * job编号
     */
    @TableField(value = "`number`")
    private Long number;

    /**
     * 操作类型 
     */
    @TableField(value = "task_type")
    private Integer taskType;

    /**
     * 创建任务的员工id
     */
    @TableField(value = "create_account_id")
    private Integer createAccountId;

    /**
     * 处理状态  0:待处理 1:处理中 2:处理完成 3:待重试 4:处理失败
     */
    @TableField(value = "process_status")
    private Integer processStatus;

    /**
     * 任务元数据 部分功能启用停用
     */
    @TableField(value = "meta_data")
    private String metaData;

    /**
     * 处理次数
     */
    @TableField(value = "process_count")
    private Integer processCount;

    /**
     * 下载状态 0 未下载 1 已下载
     */
    @TableField(value = "download_status")
    private Integer downloadStatus;

    /**
     * 处理结果
     */
    @TableField(value = "task_result")
    private String taskResult;

    /**
     * 任务系统来源 1:本系统 2:花名册 3:线索
     */
    @TableField(value = "source_type")
    private Integer sourceType;

    /**
     * 上游唯一键
     */
    @TableField(value = "source_id")
    private Long sourceId;

    /**
     * 0 正常 1 删除
     */
    @TableField(value = "is_del")
    private Boolean isDel;

    /**
     * 创建时间
     */
    @TableField(value = "create_time")
    private LocalDateTime createTime;

    /**
     * 更新时间
     */
    @TableField(value = "update_time")
    private LocalDateTime updateTime;
