def resolve_rw_dsn(db_name: str, owner_hint: str = None) -> Optional[tuple[str, int, str]]:
    """按库名从 Apollo 解析 (host, port, password)。

    扫 jdbc-mysql 里所有 url，挑 /<db_name>? 的那条，取同前缀的 password。
    """
    if db_name in _DSN_CACHE and db_name in _PW_CACHE:
        host, port = _DSN_CACHE[db_name]
        return host, port, _PW_CACHE[db_name]
    for app in APOLLO_JDBC_APPS:
        conf = _apollo_jdbc_map(app)
        # coupon-a 这类 app 压根没有 jdbc-mysql namespace（portal 实证），跳过即可
        for key, val in conf.items():
            if not isinstance(val, str) or not val.startswith("jdbc:mysql://"):
                continue
            m = re.match(r"jdbc:mysql://([^:/]+):(\d+)/([^?]+)", val)
            if not m or m.group(3) != db_name:
                continue
            host, port = m.group(1), int(m.group(2))
            # 该库被钉死到指定 host 时，只认那个 host 的那条 url
            pinned = DB_HOST_PIN.get(db_name)
            if pinned and host != pinned:
                continue
            prefix = key.rsplit(".", 1)[0]
            pw = conf.get(f"{prefix}.password") or conf.get("spring.datasource.password")
            user = conf.get(f"{prefix}.username") or RW_USER
            if not pw:
                continue
            _DSN_CACHE[db_name] = (host, port)
            _PW_CACHE[db_name] = pw
            _USER_CACHE[db_name] = user
            return host, port, pw

    # 静态列表没覆盖到：若调用方给了 owner_hint(项目名/服务名)，经青舟解析出
    # apolloId 再查一次，省去手工维护 APOLLO_JDBC_APPS
    if owner_hint:
        app_id = _apollo_id_via_qingzhou(owner_hint)
        if app_id:
            conf = _apollo_jdbc_map(app_id)
            for key, val in conf.items():
                if not isinstance(val, str) or not val.startswith("jdbc:mysql://"):
                    continue
                m = re.match(r"jdbc:mysql://([^:/]+):(\d+)/([^?]+)", val)
                if not m or m.group(3) != db_name:
                    continue
                host, port = m.group(1), int(m.group(2))
                pinned = DB_HOST_PIN.get(db_name)
                if pinned and host != pinned:
                    continue
                prefix = key.rsplit(".", 1)[0]
                pw = conf.get(f"{prefix}.password") or conf.get("spring.datasource.password")
                user = conf.get(f"{prefix}.username") or RW_USER
                if not pw:
                    continue
                _DSN_CACHE[db_name] = (host, port)
                _PW_CACHE[db_name] = pw
                _USER_CACHE[db_name] = user
                return host, port, pw
    return None


