# eco 泳道(test-eco-7 等)在 dev 下；test/test-wuhan 等主干在 test 下。先 dev 后 test。
ENV_ORDER = ["dev", "test"]

IMAGE_RE = re.compile(r"^(?P<branch>.+)-(?P<commit>[0-9a-f]{7,40})-(?P<ts>\d{14})$")


def parse_image(pod):
    """imageName 形如 `<分支>-<短commit>-<yyyyMMddHHmmss>`；返回 (branch, commit)。"""
    image = pod.get("imageName") or ""
    m = IMAGE_RE.match(image)
    return (m.group("branch"), m.group("commit")) if m else (image, "")


def fetch_groups(service_code, environment):
    ts = int(time.time() * 1000)
    r = requests.post(f"{BASE}/qingzhou/tianti/podManage/green/getServicePods?_={ts}",
                      json={"serviceCode": service_code, "environment": environment},
                      headers=H, proxies=PROXIES, verify=False, timeout=15)
    r.raise_for_status()
    payload = r.json()
    if not isinstance(payload, dict) or payload.get("code") not in (None, 0, 200):
        raise ValueError("getServicePods 查询失败，请核对登录态和服务权限")
    groups = payload.get("data")
    if "data" not in payload or (groups is not None and not isinstance(groups, list)):
        raise ValueError("getServicePods 未返回有效的分组列表")
    return groups or []


def find_namespace_group(service_code, namespace, environment=""):
    """查目标 namespace 的所有 group(可能跨集群多份)，返回 (pods, environment) 或 (None, None)。

    environment 非空时只查该 logicEnv；否则按 ENV_ORDER 依次兜底。
    同一 logicEnv 下所有同名 namespace 的 podList 合并返回，避免空 group 抢先命中。
    注意：泳道实例被下掉(缩容到 0)或新 pod 尚未调度时，青舟会把该 namespace 整个从
    getServicePods 里去掉 → 返回 None(不是空 list)，这正是「都没找到」的来源。
    """
    for env in ([environment] if environment else ENV_ORDER):
        try:
            groups = fetch_groups(service_code, env)
        except Exception as e:  # noqa: BLE001
            print(f"[fetch {env}] error: {e}", flush=True)
            continue
        hit = [g for g in groups if g.get("namespace") == namespace]
        if hit:
            pods = [p for g in hit for p in (g.get("podList") or [])]
            return pods, env
    return None, None


def probe_namespaces(service_code, namespace):
    """诊断用：扫全部 logicEnv，返回 {logicEnv: pod 数}；只含确实存在该 namespace group 的环境。
    查不到返回 {}，不区分未调度、零实例或查询失败；结合查询日志和流水线诊断。"""
    out = {}
    for env in ENV_ORDER:
        try:
            groups = fetch_groups(service_code, env)
        except Exception as e:  # noqa: BLE001
            print(f"[probe {env}] error: {e}", flush=True)
            continue
        hit = [g for g in groups if g.get("namespace") == namespace]
        if hit:
            out[env] = len([p for g in hit for p in (g.get("podList") or [])])
    return out


def latest_pod(pods):
    """取 createTime 最大的 pod(新机器)。"""
    if not pods:
        return None
    return max(pods, key=lambda p: p.get("createTime") or 0)


